  OPTIONAL { ?person dbo:birthDate ?bd1. }
  OPTIONAL { ?person dbp:birthDate ?bd2. }
  OPTIONAL { ?person rdfs:label ?label. FILTER(lang(?label) = "en" || lang(?label) = "") }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>

SELECT ?person ?bd WHERE {
  VALUES ?person { dbr:Jean-Claude_Garneau }
  OPTIONAL { ?person dbo:birthDate ?bd. }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>

SELECT ?person ?bd WHERE {
  VALUES ?person { dbr:Chae_Rim }
  OPTIONAL { ?person dbo:birthDate ?bd. }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>

SELECT ?person ?bd WHERE {
  { dbr:Jean-Claude_Garneau dbo:birthDate ?bd . BIND(dbr:Jean-Claude_Garneau AS ?person) }
  UNION
  { dbr:Chae_Rim dbo:birthDate ?bd . BIND(dbr:Chae_Rim AS ?person) }
} ORDER BY ?person

